    rows = len(grid)
    cols = len(grid[0])
    out = [row[:] for row in grid]

    # count frequencies to determine the two dominant (background) colors
    freq = Counter()
    for r in grid:
        for v in r:
            freq[v] += 1
    # two most common values are the backgrounds
    bg_vals = [x[0] for x in sorted(freq.items(), key=lambda x: -x[1])[:2]]
    bg1, bg2 = bg_vals[0], bg_vals[1]
    backgrounds = {bg1, bg2}

    # locate all non‑background cells (seeds)
    seeds = []
    for i in range(rows):
        for j in range(cols):
            val = grid[i][j]
            if val not in backgrounds:
                seeds.append((i, j, val))

    # determine for each background which seed belongs to it
    bg_to_seed = {}
    for r, c, val in seeds:
        # look at orthogonal neighbours to decide the background of this seed
        neighs = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                v = grid[nr][nc]
                if v in backgrounds:
                    neighs.append(v)
        if neighs:
            bg = Counter(neighs).most_common(1)[0][0]
        else:
            bg = bg1  # fallback
        if bg not in bg_to_seed:
            bg_to_seed[bg] = val   # assuming all seeds in the same region share the same value

    # propagate each seed along the four diagonal directions
    dirs = [(-1, -1), (-1, 1), (1, -1), (1, 1)]

    for r, c, val in seeds:
        # find the background of this seed
        neighs = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                v = grid[nr][nc]
                if v in backgrounds:
                    neighs.append(v)
        cur_bg = Counter(neighs).most_common(1)[0][0] if neighs else bg1
        other_bg = bg2 if cur_bg == bg1 else bg1

        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            while 0 <= nr < rows and 0 <= nc < cols:
                orig = grid[nr][nc]
                if orig == cur_bg:
                    out[nr][nc] = val                     # stay inside the same region
                elif orig == other_bg:
                    out[nr][nc] = bg_to_seed[other_bg]   # cross into the other region
                    break
                else:
                    # reached another seed (non‑background) – stop
